def in_bounds(map_id: int, x: int, y: int) -> bool:
    """True if (x, y) falls within map_id's own local cell grid
    (width_blocks*2, height_blocks*2) -- independent of walkability, so
    callers can tell "off this map's edge" (try a neighboring map, see
    pokemon.world_graph._cross_border) apart from "on this map but a
    wall/water/obstacle" (see is_walkable). False if map_id has no
    MAPS_BY_ID entry."""
    entry = MAPS_BY_ID.get(map_id)
    if entry is None:
        return False
    width_cells = entry[1] * 2
    height_cells = entry[2] * 2
    return 0 <= x < width_cells and 0 <= y < height_cells


def _lookup(grid_by_map: dict[int, bytes], map_id: int, x: int, y: int) -> bool:
    grid = grid_by_map.get(map_id)
    entry = MAPS_BY_ID.get(map_id)
    if grid is None or entry is None or not in_bounds(map_id, x, y):
        return False
    width_cells = entry[1] * 2
    idx = y * width_cells + x
    return bool(grid[idx // 8] & (1 << (idx % 8)))


def is_walkable(map_id: int, x: int, y: int) -> bool:
    """True if (x, y) on map_id is a walkable overworld tile.

    False for a map with no static collision data, an out-of-bounds
    (x, y), or a tile outside the walkable set."""
    return _lookup(MAP_COLLISION, map_id, x, y)


def is_grass(map_id: int, x: int, y: int) -> bool:
    """True if (x, y) on map_id is the tileset's designated grass tile
    (a strict subset of is_walkable -- see GRASS_COLLISION). False for a
    tileset with no grass tile at all (e.g. caves), not just an
    out-of-bounds/non-grass (x, y)."""
    return _lookup(GRASS_COLLISION, map_id, x, y)


def walkable_tile_count(map_id: int) -> int:
    """Total walkable cells on map_id (population count of its packed
    bitmap -- trailing pad bits past width_cells*height_cells are always
    0, so they never inflate this), or 0 if map_id has no static
    collision data. The natural "how much of this map is there to
    discover" denominator for a live position_visit_counts coverage
    stat (see run_eval_ppo.py's -v/-vv [step] line)."""
    grid = MAP_COLLISION.get(map_id)
    if grid is None:
        return 0
    return int.from_bytes(grid, "little").bit_count()


def flood_grass_island(map_id: int, x0: int, y0: int) -> set[tuple[int, int]]:
    """4-connected grass-tile component reachable from (x0, y0) on
    map_id, i.e. the grass "island" the tile sits in -- NOT the whole
    connected walkable area (see the module docstring: on an overworld
    map, grass patches directly abut the path with no wall between them,
    so flooding is_walkable would swallow the entire route instead of
    stopping at the patch's edge). Empty set if (x0, y0) itself is not
    grass (see is_grass -- no static data for map_id, out-of-bounds, a
    non-grass tile, or a tileset with no grass tile at all). Used by
    Data._mark_wild_grass_island.
    """
    if not is_grass(map_id, x0, y0):
        return set()
    seen = {(x0, y0)}
    queue = deque([(x0, y0)])
    while queue:
        x, y = queue.popleft()
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if (nx, ny) not in seen and is_grass(map_id, nx, ny):
                seen.add((nx, ny))
                queue.append((nx, ny))
    return seen
